bd->ExternalMouseDisplay = external_mouse_display;
if (external_mouse_display)
{
    io.BackendFlags &= ~(ImGuiBackendFlags_HasMouseCursors | ImGuiBackendFlags_HasSetMousePos);
    io.SetClipboardTextFn = nullptr;
    io.GetClipboardTextFn = nullptr;
    io.SetPlatformImeDataFn = nullptr;
    io.ClipboardUserData = nullptr;
    return true;
}

bool ImGui_ImplSDL2_InitForOther(SDL_Window* window, bool external_mouse_display)
{
    return ImGui_ImplSDL2_Init(window, nullptr, external_mouse_display);
}

if (!bd->ExternalMouseDisplay)
    for (ImGuiMouseCursor cursor_n = 0; cursor_n < ImGuiMouseCursor_COUNT; cursor_n++)
        SDL_FreeCursor(bd->MouseCursors[cursor_n]);

if (!bd->ExternalMouseDisplay)
{
    // Setup display size (every frame to accommodate for window resizing)
    int w, h;
    int display_w, display_h;
    SDL_GetWindowSize(bd->Window, &w, &h);
    if (SDL_GetWindowFlags(bd->Window) & SDL_WINDOW_MINIMIZED)
        w = h = 0;
    if (bd->Renderer != nullptr)
        SDL_GetRendererOutputSize(bd->Renderer, &display_w, &display_h);
    else
        SDL_GL_GetDrawableSize(bd->Window, &display_w, &display_h);
    io.DisplaySize = ImVec2((float)w, (float)h);
    if (w > 0 && h > 0)
        io.DisplayFramebufferScale = ImVec2((float)display_w / w, (float)display_h / h);
}
